--------------------------------------------------------
--  DDL for Table HASTALAR
--------------------------------------------------------

  CREATE TABLE "HASTALAR" 
   (	"RECETENO" VARCHAR2(26 BYTE), 
	"KIMLIKNO" NUMBER(38,0), 
	"ISIM" VARCHAR2(26 BYTE), 
	"SOYISIM" VARCHAR2(26 BYTE), 
	"TELNO" NUMBER(38,0), 
	"RECETETARIHI" DATE
   ) ;
--------------------------------------------------------
--  DDL for Table HASTANE
--------------------------------------------------------

  CREATE TABLE "HASTANE" 
   (	"HASTANEID" NUMBER(38,0), 
	"HASTANEADI" VARCHAR2(128 BYTE)
   ) ;
--------------------------------------------------------
--  DDL for Table HEKIMLER
--------------------------------------------------------

  CREATE TABLE "HEKIMLER" 
   (	"HEKIMADI" VARCHAR2(26 BYTE), 
	"HEKIMSOYADI" VARCHAR2(26 BYTE), 
	"HASTANEID" NUMBER(38,0)
   ) ;
--------------------------------------------------------
--  DDL for Table ILAC
--------------------------------------------------------

  CREATE TABLE "ILAC" 
   (	"ILACID" VARCHAR2(26 BYTE), 
	"BARKODU" NUMBER(38,0), 
	"ADI" VARCHAR2(128 BYTE), 
	"FIYAT" NUMBER(38,2), 
	"FIRMAID" NUMBER(38,0), 
	"TARIH" DATE, 
	"KDVID" NUMBER(38,0)
   ) ;
--------------------------------------------------------
--  DDL for Table ILACDEPO
--------------------------------------------------------

  CREATE TABLE "ILACDEPO" 
   (	"ID" VARCHAR2(26 BYTE), 
	"STOKADET" NUMBER(38,0)
   ) ;
--------------------------------------------------------
--  DDL for Table ILACFIRMA
--------------------------------------------------------

  CREATE TABLE "ILACFIRMA" 
   (	"FIRMAID" NUMBER(38,0), 
	"FIRMAISIM" VARCHAR2(150 BYTE)
   ) ;
--------------------------------------------------------
--  DDL for Table KDV
--------------------------------------------------------

  CREATE TABLE "KDV" 
   (	"KDVID" NUMBER(38,0), 
	"KDV" NUMBER(38,2)
   ) ;
--------------------------------------------------------
--  DDL for Table PERSONEL
--------------------------------------------------------

  CREATE TABLE "PERSONEL" 
   (	"EZCPID" NUMBER(38,0), 
	"ISIM" VARCHAR2(26 BYTE), 
	"SOYISIM" VARCHAR2(26 BYTE), 
	"KIMLIKNO" NUMBER(38,0), 
	"UNVANID" NUMBER(38,0)
   ) ;
--------------------------------------------------------
--  DDL for Table RECETEILAC
--------------------------------------------------------

  CREATE TABLE "RECETEILAC" 
   (	"RECETENO" VARCHAR2(26 BYTE), 
	"ILACID" VARCHAR2(26 BYTE)
   ) ;
--------------------------------------------------------
--  DDL for Table SATILANILAC
--------------------------------------------------------

  CREATE TABLE "SATILANILAC" 
